#!/usr/bin/env python3
"""Apply the reviewed release publication and descriptor-pinning remediation."""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

BUILD_HELPERS = '\ndef _absolute_path(path: Path) -> Path:\n    return Path(os.path.abspath(os.fspath(path)))\n\n\ndef _stable_identity(metadata: os.stat_result) -> tuple[int, ...]:\n    return (\n        metadata.st_dev,\n        metadata.st_ino,\n        metadata.st_mode,\n        metadata.st_nlink,\n        metadata.st_size,\n        metadata.st_mtime_ns,\n        metadata.st_ctime_ns,\n    )\n\n\ndef _open_directory(path: Path) -> int:\n    # Open every directory component without following symbolic links.\n    absolute = _absolute_path(path)\n    flags = (\n        os.O_RDONLY\n        | getattr(os, "O_DIRECTORY", 0)\n        | getattr(os, "O_CLOEXEC", 0)\n        | getattr(os, "O_NOFOLLOW", 0)\n    )\n    descriptor = os.open("/", flags)\n    try:\n        for part in absolute.parts[1:]:\n            next_descriptor = os.open(part, flags, dir_fd=descriptor)\n            os.close(descriptor)\n            descriptor = next_descriptor\n        return descriptor\n    except Exception:\n        os.close(descriptor)\n        raise\n\n\ndef _open_pinned_regular(path: Path) -> tuple[int, int, str, os.stat_result]:\n    # Open one file exactly once relative to a pinned, no-follow parent.\n    absolute = _absolute_path(path)\n    parent = _open_directory(absolute.parent)\n    name = absolute.name\n    try:\n        before = os.stat(name, dir_fd=parent, follow_symlinks=False)\n        flags = (\n            os.O_RDONLY\n            | getattr(os, "O_CLOEXEC", 0)\n            | getattr(os, "O_NOFOLLOW", 0)\n        )\n        descriptor = os.open(name, flags, dir_fd=parent)\n        opened = os.fstat(descriptor)\n        if (\n            before.st_dev != opened.st_dev\n            or before.st_ino != opened.st_ino\n            or before.st_mode != opened.st_mode\n            or before.st_nlink != opened.st_nlink\n            or before.st_size != opened.st_size\n        ):\n            os.close(descriptor)\n            raise PackageError(f"input changed while opening: {absolute}")\n        return descriptor, parent, name, opened\n    except Exception:\n        os.close(parent)\n        raise\n\n\ndef _validate_pinned(\n    descriptor: int,\n    parent: int,\n    name: str,\n    original: os.stat_result,\n    path: Path,\n) -> None:\n    opened = os.fstat(descriptor)\n    try:\n        current = os.stat(name, dir_fd=parent, follow_symlinks=False)\n    except OSError as error:\n        raise PackageError(f"input disappeared while reading: {path}") from error\n    if (\n        _stable_identity(opened) != _stable_identity(original)\n        or current.st_dev != opened.st_dev\n        or current.st_ino != opened.st_ino\n    ):\n        raise PackageError(f"input changed or was replaced while reading: {path}")\n\n\ndef _copy_to_snapshot(\n    descriptor: int,\n    parent: int,\n    name: str,\n    metadata: os.stat_result,\n    source: Path,\n) -> tuple[BinaryIO, str]:\n    snapshot = tempfile.TemporaryFile(mode="w+b")\n    digest = hashlib.sha256()\n    total = 0\n    try:\n        while True:\n            chunk = os.read(descriptor, 1024 * 1024)\n            if not chunk:\n                break\n            total += len(chunk)\n            if total > metadata.st_size or total > MAX_FILE_BYTES:\n                raise PackageError(f"file changed or exceeds size bound: {source}")\n            snapshot.write(chunk)\n            digest.update(chunk)\n        if total != metadata.st_size:\n            raise PackageError(f"file size changed while reading: {source}")\n        _validate_pinned(descriptor, parent, name, metadata, source)\n        snapshot.flush()\n        snapshot.seek(0)\n        return snapshot, digest.hexdigest()\n    except Exception:\n        snapshot.close()\n        raise\n\n\ndef _write_all(descriptor: int, content: bytes) -> None:\n    view = memoryview(content)\n    while view:\n        written = os.write(descriptor, view)\n        if written <= 0:\n            raise OSError("short write while publishing release output")\n        view = view[written:]\n\n\ndef _publish_noreplace(directory_fd: int, temporary_name: str, final_name: str) -> None:\n    # Atomic same-directory publication. link(2) fails with EEXIST and never replaces.\n    os.link(\n        temporary_name,\n        final_name,\n        src_dir_fd=directory_fd,\n        dst_dir_fd=directory_fd,\n        follow_symlinks=False,\n    )\n'
BUILD_COLLECT = '\ndef close_payload(payload: Iterable[PayloadFile]) -> None:\n    for item in payload:\n        try:\n            item.snapshot.close()\n        except OSError:\n            pass\n\n\ndef collect_payload(root: Path) -> list[PayloadFile]:\n    root = _absolute_path(root)\n    root_descriptor = _open_directory(root)\n    try:\n        root_metadata = os.fstat(root_descriptor)\n        if not stat.S_ISDIR(root_metadata.st_mode):\n            raise PackageError("install root must be a real directory")\n    finally:\n        os.close(root_descriptor)\n\n    payload: list[PayloadFile] = []\n    total = 0\n    try:\n        for directory, names, files in os.walk(root, topdown=True, followlinks=False):\n            directory_path = Path(directory)\n            for name in list(names):\n                child = directory_path / name\n                metadata = child.lstat()\n                if stat.S_ISLNK(metadata.st_mode):\n                    raise PackageError(f"symlinked directory is forbidden: {child}")\n                if not stat.S_ISDIR(metadata.st_mode):\n                    raise PackageError(f"special directory entry is forbidden: {child}")\n            names.sort()\n            files.sort()\n            for name in files:\n                source = directory_path / name\n                relative = canonical_relative(source, root)\n                if _looks_private(relative):\n                    raise PackageError(\n                        f"private-key or secret-like path is forbidden: {relative}"\n                    )\n                descriptor = parent = -1\n                snapshot: BinaryIO | None = None\n                try:\n                    descriptor, parent, pinned_name, metadata = _open_pinned_regular(source)\n                    if not stat.S_ISREG(metadata.st_mode):\n                        raise PackageError(f"only regular files may be packaged: {relative}")\n                    if metadata.st_nlink != 1:\n                        raise PackageError(f"hard-linked file is forbidden: {relative}")\n                    if metadata.st_mode & (stat.S_ISUID | stat.S_ISGID):\n                        raise PackageError(f"setuid/setgid file is forbidden: {relative}")\n                    if metadata.st_size > MAX_FILE_BYTES:\n                        raise PackageError(f"file exceeds release size bound: {relative}")\n                    total += metadata.st_size\n                    if total > MAX_TOTAL_BYTES:\n                        raise PackageError("release payload exceeds total size bound")\n                    snapshot, digest = _copy_to_snapshot(\n                        descriptor, parent, pinned_name, metadata, source\n                    )\n                    payload.append(\n                        PayloadFile(\n                            path=relative,\n                            source=source,\n                            snapshot=snapshot,\n                            size=metadata.st_size,\n                            mode=_file_mode(metadata),\n                            sha256=digest,\n                        )\n                    )\n                    snapshot = None\n                finally:\n                    if snapshot is not None:\n                        snapshot.close()\n                    if descriptor >= 0:\n                        os.close(descriptor)\n                    if parent >= 0:\n                        os.close(parent)\n        if not payload:\n            raise PackageError("install root is empty")\n        return sorted(payload, key=lambda item: item.path)\n    except Exception:\n        close_payload(payload)\n        raise\n'
BUILD_ARCHIVE = '\ndef archive_bytes(\n    payload: list[PayloadFile], manifest: dict[str, Any], version: str, profile: str, epoch: int\n) -> tuple[bytes, str]:\n    root_name = f"heptatrader-{version}-{profile}"\n    manifest_bytes = canonical_json(manifest)\n    raw_tar = io.BytesIO()\n    with tarfile.open(fileobj=raw_tar, mode="w", format=tarfile.GNU_FORMAT) as archive:\n        archive.addfile(\n            _tar_info(f"{root_name}/manifest.json", len(manifest_bytes), 0o644, epoch),\n            io.BytesIO(manifest_bytes),\n        )\n        for item in payload:\n            if item.snapshot.closed:\n                raise PackageError(f"payload snapshot is closed: {item.path}")\n            item.snapshot.seek(0)\n            archive.addfile(\n                _tar_info(f"{root_name}/{item.path}", item.size, item.mode, epoch),\n                item.snapshot,\n            )\n            if item.snapshot.tell() != item.size:\n                raise PackageError(f"payload snapshot size changed: {item.path}")\n            item.snapshot.seek(0)\n            digest = hashlib.sha256()\n            for chunk in iter(lambda: item.snapshot.read(1024 * 1024), b""):\n                digest.update(chunk)\n            if digest.hexdigest() != item.sha256:\n                raise PackageError(f"payload snapshot digest changed: {item.path}")\n            item.snapshot.seek(0)\n\n    compressed = io.BytesIO()\n    with gzip.GzipFile(\n        filename="", mode="wb", compresslevel=9, fileobj=compressed, mtime=epoch\n    ) as output:\n        output.write(raw_tar.getvalue())\n    return compressed.getvalue(), sha256_bytes(manifest_bytes)\n'
BUILD_PUBLISH = '\n@dataclass(frozen=True)\nclass PublishedOutput:\n    path: Path\n    device: int\n    inode: int\n\n\ndef _prepare_output_parents(paths: Iterable[Path]) -> None:\n    for path in paths:\n        _absolute_path(path).parent.mkdir(parents=True, exist_ok=True)\n\n\ndef _write_atomic(path: Path, content: bytes, mode: int) -> PublishedOutput:\n    path = _absolute_path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    directory = _open_directory(path.parent)\n    descriptor = -1\n    temporary_name = ""\n    published = False\n    identity: os.stat_result | None = None\n    try:\n        for _ in range(128):\n            candidate = f".{path.name}.{os.getpid()}.{secrets.token_hex(16)}"\n            try:\n                descriptor = os.open(\n                    candidate,\n                    os.O_WRONLY\n                    | os.O_CREAT\n                    | os.O_EXCL\n                    | getattr(os, "O_CLOEXEC", 0)\n                    | getattr(os, "O_NOFOLLOW", 0),\n                    mode,\n                    dir_fd=directory,\n                )\n                temporary_name = candidate\n                break\n            except FileExistsError:\n                continue\n        if descriptor < 0:\n            raise PackageError(f"cannot allocate a private output name: {path}")\n        os.fchmod(descriptor, mode)\n        _write_all(descriptor, content)\n        os.fsync(descriptor)\n        identity = os.fstat(descriptor)\n        try:\n            _publish_noreplace(directory, temporary_name, path.name)\n        except FileExistsError as error:\n            raise PackageError(f"refusing to replace existing output: {path}") from error\n        published = True\n        os.unlink(temporary_name, dir_fd=directory)\n        temporary_name = ""\n        os.fsync(directory)\n        return PublishedOutput(path, identity.st_dev, identity.st_ino)\n    except Exception:\n        if published and identity is not None:\n            try:\n                current = os.stat(path.name, dir_fd=directory, follow_symlinks=False)\n                if current.st_dev == identity.st_dev and current.st_ino == identity.st_ino:\n                    os.unlink(path.name, dir_fd=directory)\n                    os.fsync(directory)\n            except OSError:\n                pass\n        raise\n    finally:\n        if temporary_name:\n            try:\n                os.unlink(temporary_name, dir_fd=directory)\n            except OSError:\n                pass\n        if descriptor >= 0:\n            os.close(descriptor)\n        os.close(directory)\n\n\ndef _remove_published(output: PublishedOutput) -> None:\n    directory = _open_directory(output.path.parent)\n    try:\n        current = os.stat(output.path.name, dir_fd=directory, follow_symlinks=False)\n        if current.st_dev != output.device or current.st_ino != output.inode:\n            raise PackageError(\n                f"refusing to remove a replaced rollback output: {output.path}"\n            )\n        os.unlink(output.path.name, dir_fd=directory)\n        os.fsync(directory)\n    finally:\n        os.close(directory)\n'
BUILD_PACKAGE = '\ndef package_install_root(\n    install_root: Path,\n    output: Path,\n    *,\n    version: str,\n    profile: str,\n    source_sha: str,\n    source_date_epoch: int,\n) -> dict[str, Any]:\n    validate_identity(version, profile, source_sha, source_date_epoch)\n    output = _absolute_path(output)\n    if output.suffix not in {".gz", ".tgz"}:\n        raise PackageError("release output must end in .tar.gz or .tgz")\n    digest_path = Path(str(output) + ".sha256")\n    receipt_path = Path(str(output) + ".receipt.json")\n    _prepare_output_parents((output, digest_path, receipt_path))\n\n    payload: list[PayloadFile] = []\n    try:\n        payload = collect_payload(install_root)\n        manifest = build_manifest(payload, version, profile, source_sha, source_date_epoch)\n        archive, manifest_sha256 = archive_bytes(\n            payload, manifest, version, profile, source_date_epoch\n        )\n        package_sha256 = sha256_bytes(archive)\n        receipt = {\n            "schema": RECEIPT_SCHEMA,\n            "version": version,\n            "profile": profile,\n            "source_sha": source_sha,\n            "source_date_epoch": source_date_epoch,\n            "package_file": output.name,\n            "package_sha256": package_sha256,\n            "manifest_sha256": manifest_sha256,\n            "file_count": len(payload),\n            "authorization_effect": "NONE",\n            "paper_authorized": False,\n            "live_authorized": False,\n        }\n    finally:\n        close_payload(payload)\n\n    written: list[PublishedOutput] = []\n    try:\n        written.append(_write_atomic(output, archive, 0o644))\n        written.append(\n            _write_atomic(\n                digest_path,\n                f"{package_sha256}  {output.name}\\n".encode("ascii"),\n                0o644,\n            )\n        )\n        written.append(_write_atomic(receipt_path, canonical_json(receipt), 0o600))\n    except Exception:\n        for published in reversed(written):\n            try:\n                _remove_published(published)\n            except (OSError, PackageError):\n                pass\n        raise\n    return receipt\n'
PREFLIGHT_HELPERS = '\ndef _absolute_path(path: Path) -> Path:\n    return Path(os.path.abspath(os.fspath(path)))\n\n\ndef _stable_identity(metadata: os.stat_result) -> tuple[int, ...]:\n    return (\n        metadata.st_dev,\n        metadata.st_ino,\n        metadata.st_mode,\n        metadata.st_nlink,\n        metadata.st_size,\n        metadata.st_mtime_ns,\n        metadata.st_ctime_ns,\n    )\n\n\ndef _open_directory(path: Path) -> int:\n    absolute = _absolute_path(path)\n    flags = (\n        os.O_RDONLY\n        | getattr(os, "O_DIRECTORY", 0)\n        | getattr(os, "O_CLOEXEC", 0)\n        | getattr(os, "O_NOFOLLOW", 0)\n    )\n    descriptor = os.open("/", flags)\n    try:\n        for part in absolute.parts[1:]:\n            next_descriptor = os.open(part, flags, dir_fd=descriptor)\n            os.close(descriptor)\n            descriptor = next_descriptor\n        return descriptor\n    except Exception:\n        os.close(descriptor)\n        raise\n\n\ndef _open_pinned_regular(\n    path: Path, label: str\n) -> tuple[BinaryIO, int, str, os.stat_result]:\n    absolute = _absolute_path(path)\n    parent = _open_directory(absolute.parent)\n    try:\n        before = os.stat(absolute.name, dir_fd=parent, follow_symlinks=False)\n        flags = (\n            os.O_RDONLY\n            | getattr(os, "O_CLOEXEC", 0)\n            | getattr(os, "O_NOFOLLOW", 0)\n        )\n        descriptor = os.open(absolute.name, flags, dir_fd=parent)\n        opened = os.fstat(descriptor)\n        if (\n            not stat.S_ISREG(opened.st_mode)\n            or opened.st_nlink != 1\n            or before.st_dev != opened.st_dev\n            or before.st_ino != opened.st_ino\n            or before.st_mode != opened.st_mode\n            or before.st_nlink != opened.st_nlink\n            or before.st_size != opened.st_size\n        ):\n            os.close(descriptor)\n            raise PreflightError(f"{label} must be a stable regular single-link file")\n        return os.fdopen(descriptor, "rb", closefd=True), parent, absolute.name, opened\n    except Exception:\n        os.close(parent)\n        raise\n\n\ndef _validate_pinned(\n    stream: BinaryIO,\n    parent: int,\n    name: str,\n    original: os.stat_result,\n    label: str,\n) -> None:\n    opened = os.fstat(stream.fileno())\n    try:\n        current = os.stat(name, dir_fd=parent, follow_symlinks=False)\n    except OSError as error:\n        raise PreflightError(f"{label} disappeared while being inspected") from error\n    if (\n        _stable_identity(opened) != _stable_identity(original)\n        or current.st_dev != opened.st_dev\n        or current.st_ino != opened.st_ino\n    ):\n        raise PreflightError(f"{label} changed or was replaced while being inspected")\n\n\n@dataclass\nclass PinnedSnapshot:\n    source: BinaryIO\n    parent: int\n    name: str\n    metadata: os.stat_result\n    snapshot: BinaryIO\n    sha256: str\n    label: str\n    closed: bool = False\n\n    def validate(self) -> None:\n        _validate_pinned(\n            self.source, self.parent, self.name, self.metadata, self.label\n        )\n\n    def close(self) -> None:\n        if self.closed:\n            return\n        error: Exception | None = None\n        try:\n            self.validate()\n        except Exception as caught:\n            error = caught\n        try:\n            self.snapshot.close()\n        finally:\n            try:\n                self.source.close()\n            finally:\n                os.close(self.parent)\n                self.closed = True\n        if error is not None:\n            raise error\n\n\ndef _snapshot_pinned_file(\n    path: Path, label: str, maximum: int | None = None\n) -> PinnedSnapshot:\n    source, parent, name, metadata = _open_pinned_regular(path, label)\n    snapshot = tempfile.TemporaryFile(mode="w+b")\n    digest = hashlib.sha256()\n    total = 0\n    try:\n        while True:\n            chunk = source.read(1024 * 1024)\n            if not chunk:\n                break\n            total += len(chunk)\n            if maximum is not None and total > maximum:\n                raise PreflightError(f"{label} exceeds size bound")\n            if total > metadata.st_size:\n                raise PreflightError(f"{label} size changed while reading")\n            snapshot.write(chunk)\n            digest.update(chunk)\n        if total != metadata.st_size:\n            raise PreflightError(f"{label} size changed while reading")\n        _validate_pinned(source, parent, name, metadata, label)\n        snapshot.flush()\n        snapshot.seek(0)\n        source.seek(0)\n        return PinnedSnapshot(\n            source=source,\n            parent=parent,\n            name=name,\n            metadata=metadata,\n            snapshot=snapshot,\n            sha256=digest.hexdigest(),\n            label=label,\n        )\n    except Exception:\n        snapshot.close()\n        source.close()\n        os.close(parent)\n        raise\n\n\ndef _read_pinned_bytes(path: Path, maximum: int, label: str) -> bytes:\n    pinned = _snapshot_pinned_file(path, label, maximum)\n    try:\n        return _read_bounded(pinned.snapshot, maximum, label)\n    finally:\n        pinned.close()\n\n\ndef _write_all(descriptor: int, content: bytes) -> None:\n    view = memoryview(content)\n    while view:\n        written = os.write(descriptor, view)\n        if written <= 0:\n            raise OSError("short write while publishing preflight receipt")\n        view = view[written:]\n\n\ndef _publish_noreplace(directory_fd: int, temporary_name: str, final_name: str) -> None:\n    os.link(\n        temporary_name,\n        final_name,\n        src_dir_fd=directory_fd,\n        dst_dir_fd=directory_fd,\n        follow_symlinks=False,\n    )\n'
PREFLIGHT_LOAD_POLICY = '\ndef _load_policy(path: Path) -> dict[str, Any]:\n    value = parse_json_bytes(\n        _read_pinned_bytes(_absolute_path(path), 4 * 1024 * 1024, "policy"),\n        str(path),\n    )\n    if not isinstance(value, dict) or value.get("schema") != POLICY_SCHEMA:\n        raise PreflightError("unsupported preflight policy")\n    profiles = value.get("profiles")\n    if not isinstance(profiles, dict) or not profiles:\n        raise PreflightError("preflight policy profiles are missing")\n    for key in (\n        "maximum_archive_members",\n        "maximum_member_bytes",\n        "maximum_total_unpacked_bytes",\n    ):\n        item = value.get(key)\n        if not isinstance(item, int) or isinstance(item, bool) or item <= 0:\n            raise PreflightError(f"invalid policy bound: {key}")\n    suffixes = value.get("private_key_suffixes")\n    if (\n        not isinstance(suffixes, list)\n        or any(not isinstance(item, str) or not item.startswith(".") for item in suffixes)\n    ):\n        raise PreflightError("private-key suffix policy is invalid")\n    return value\n'
PREFLIGHT_INSPECT = '\ndef _inspect_archive_stream(\n    stream: BinaryIO,\n    policy: dict[str, Any],\n    profile: str,\n) -> tuple[dict[str, Any], bytes]:\n    maximum_members = policy["maximum_archive_members"]\n    maximum_member = policy["maximum_member_bytes"]\n    maximum_total = policy["maximum_total_unpacked_bytes"]\n    stream.seek(0)\n    try:\n        archive = tarfile.open(fileobj=stream, mode="r:gz")\n    except (tarfile.TarError, OSError) as error:\n        raise PreflightError(f"artifact is not a valid gzip tar archive: {error}") from error\n\n    with archive:\n        members = archive.getmembers()\n        if not members or len(members) > maximum_members:\n            raise PreflightError("archive member count is outside policy")\n        seen: set[str] = set()\n        roots: set[str] = set()\n        files_by_relative: dict[str, tarfile.TarInfo] = {}\n        manifest_member: tarfile.TarInfo | None = None\n        total = 0\n        for member in members:\n            parts = _canonical_member_name(member.name)\n            roots.add(parts[0])\n            if member.name in seen:\n                raise PreflightError(f"duplicate archive member: {member.name}")\n            seen.add(member.name)\n            if not (member.isdir() or member.isreg()):\n                raise PreflightError(\n                    f"links and special archive entries are forbidden: {member.name}"\n                )\n            if member.uid != 0 or member.gid != 0:\n                raise PreflightError(\n                    f"archive ownership is not normalized: {member.name}"\n                )\n            if member.mtime <= 0:\n                raise PreflightError(f"archive timestamp is invalid: {member.name}")\n            if member.isreg():\n                if member.size < 0 or member.size > maximum_member:\n                    raise PreflightError(\n                        f"archive member size is outside policy: {member.name}"\n                    )\n                total += member.size\n                if total > maximum_total:\n                    raise PreflightError("archive unpacked size exceeds policy")\n        if len(roots) != 1:\n            raise PreflightError("archive must have exactly one top-level directory")\n        root_name = next(iter(roots))\n        if not root_name.startswith("heptatrader-"):\n            raise PreflightError("archive root name is not canonical")\n\n        for member in members:\n            if not member.isreg():\n                continue\n            prefix = root_name + "/"\n            if not member.name.startswith(prefix):\n                raise PreflightError("archive member escaped the package root")\n            relative = member.name[len(prefix):]\n            if relative == "manifest.json":\n                if manifest_member is not None:\n                    raise PreflightError("archive contains multiple manifests")\n                manifest_member = member\n            else:\n                files_by_relative[relative] = member\n        if manifest_member is None:\n            raise PreflightError("release manifest is missing")\n        manifest_stream = archive.extractfile(manifest_member)\n        if manifest_stream is None:\n            raise PreflightError("release manifest is unreadable")\n        with manifest_stream:\n            manifest_bytes = _read_bounded(\n                manifest_stream, 4 * 1024 * 1024, "manifest"\n            )\n        manifest = parse_json_bytes(manifest_bytes, "manifest")\n        manifest_files = _check_manifest_shape(manifest, profile)\n        if manifest["source_date_epoch"] != manifest_member.mtime:\n            raise PreflightError("manifest and archive timestamp identity mismatch")\n\n        expected_paths = {item["path"] for item in manifest_files}\n        if set(files_by_relative) != expected_paths:\n            missing = sorted(expected_paths - set(files_by_relative))\n            extra = sorted(set(files_by_relative) - expected_paths)\n            raise PreflightError(\n                f"archive payload differs from manifest: missing={missing}, extra={extra}"\n            )\n        suffixes = {item.lower() for item in policy["private_key_suffixes"]}\n        for item in manifest_files:\n            path = item["path"]\n            if _private_path(path, suffixes):\n                raise PreflightError(\n                    f"private-key or secret-like path is forbidden: {path}"\n                )\n            member = files_by_relative[path]\n            if member.size != item["size"]:\n                raise PreflightError(f"payload size mismatch: {path}")\n            if member.mode & 0o777 != item["mode"]:\n                raise PreflightError(f"payload mode mismatch: {path}")\n            if member.mtime != manifest["source_date_epoch"]:\n                raise PreflightError(f"payload timestamp mismatch: {path}")\n            if _hash_member(archive, member, maximum_member) != item["sha256"]:\n                raise PreflightError(f"payload digest mismatch: {path}")\n\n        selected = policy["profiles"].get(profile)\n        if not isinstance(selected, dict):\n            raise PreflightError(\n                f"profile is absent from preflight policy: {profile}"\n            )\n        required = selected.get("required_package_paths")\n        if not isinstance(required, list) or any(\n            not isinstance(item, str) for item in required\n        ):\n            raise PreflightError("required package path policy is invalid")\n        absent = sorted(set(required) - expected_paths)\n        if absent:\n            raise PreflightError(\n                "required package files are missing: " + ", ".join(absent)\n            )\n\n        build_info_path = "share/heptatrader/heptatrader-build-info.json"\n        build_info_member = files_by_relative.get(build_info_path)\n        if build_info_member is None:\n            raise PreflightError("installed build metadata is missing")\n        build_info_stream = archive.extractfile(build_info_member)\n        if build_info_stream is None:\n            raise PreflightError("installed build metadata is unreadable")\n        with build_info_stream:\n            build_info = parse_json_bytes(\n                _read_bounded(\n                    build_info_stream, 64 * 1024, "installed build metadata"\n                ),\n                "installed build metadata",\n            )\n        if not isinstance(build_info, dict):\n            raise PreflightError("installed build metadata must be an object")\n        if (\n            build_info.get("paper_authorized") is not False\n            or build_info.get("live_authorized") is not False\n        ):\n            raise PreflightError(\n                "installed build metadata attempted to claim authorization"\n            )\n        if profile == "ib-paper" and build_info.get("ib_api_compiled") is not True:\n            raise PreflightError("IB PAPER package was not built with the IB API")\n        if profile == "core" and build_info.get("ib_api_compiled") is not False:\n            raise PreflightError(\n                "core package unexpectedly contains an IB-enabled build"\n            )\n\n    return manifest, manifest_bytes\n\n\ndef inspect_archive(\n    artifact: Path, expected_sha256: str, policy: dict[str, Any], profile: str\n) -> tuple[dict[str, Any], str, str]:\n    if SHA256_RE.fullmatch(expected_sha256) is None:\n        raise PreflightError("expected artifact SHA-256 is not canonical")\n    pinned = _snapshot_pinned_file(_absolute_path(artifact), "artifact")\n    try:\n        if pinned.sha256 != expected_sha256:\n            raise PreflightError("artifact SHA-256 mismatch")\n        manifest, manifest_bytes = _inspect_archive_stream(\n            pinned.snapshot, policy, profile\n        )\n        return (\n            manifest,\n            pinned.sha256,\n            hashlib.sha256(manifest_bytes).hexdigest(),\n        )\n    finally:\n        pinned.close()\n'
PREFLIGHT_WRITE = '\ndef _write_private_receipt(path: Path, value: dict[str, Any]) -> None:\n    path = _absolute_path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    directory = _open_directory(path.parent)\n    descriptor = -1\n    temporary_name = ""\n    published = False\n    identity: os.stat_result | None = None\n    try:\n        for _ in range(128):\n            candidate = f".{path.name}.{os.getpid()}.{secrets.token_hex(16)}"\n            try:\n                descriptor = os.open(\n                    candidate,\n                    os.O_WRONLY\n                    | os.O_CREAT\n                    | os.O_EXCL\n                    | getattr(os, "O_CLOEXEC", 0)\n                    | getattr(os, "O_NOFOLLOW", 0),\n                    0o600,\n                    dir_fd=directory,\n                )\n                temporary_name = candidate\n                break\n            except FileExistsError:\n                continue\n        if descriptor < 0:\n            raise PreflightError(\n                f"cannot allocate a private receipt name: {path}"\n            )\n        os.fchmod(descriptor, 0o600)\n        _write_all(descriptor, canonical_json(value))\n        os.fsync(descriptor)\n        identity = os.fstat(descriptor)\n        try:\n            _publish_noreplace(directory, temporary_name, path.name)\n        except FileExistsError as error:\n            raise PreflightError(\n                f"refusing to replace existing receipt: {path}"\n            ) from error\n        published = True\n        os.unlink(temporary_name, dir_fd=directory)\n        temporary_name = ""\n        os.fsync(directory)\n    except Exception:\n        if published and identity is not None:\n            try:\n                current = os.stat(\n                    path.name, dir_fd=directory, follow_symlinks=False\n                )\n                if (\n                    current.st_dev == identity.st_dev\n                    and current.st_ino == identity.st_ino\n                ):\n                    os.unlink(path.name, dir_fd=directory)\n                    os.fsync(directory)\n            except OSError:\n                pass\n        raise\n    finally:\n        if temporary_name:\n            try:\n                os.unlink(temporary_name, dir_fd=directory)\n            except OSError:\n                pass\n        if descriptor >= 0:\n            os.close(descriptor)\n        os.close(directory)\n'
RACE_TEST = 'from __future__ import annotations\n\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport sys\nimport tarfile\nimport tempfile\nimport unittest\nfrom unittest import mock\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT / "scripts"))\n\nimport build_release_package as release  # noqa: E402\nimport hepta_preflight as preflight  # noqa: E402\n\n\nSOURCE_SHA = "1" * 40\nEPOCH = 1700000000\nVERSION = "0.1.0-beta.1"\nPOLICY = ROOT / "docs/preflight-policy-v1.json"\n\n\ndef fixture_tree(root: Path, marker: str = "original") -> Path:\n    paths = [\n        "bin/hepta-executiond",\n        "bin/hepta-sessionctl",\n        "bin/hepta-tool-gatewayd",\n        "bin/hepta-preflight",\n        "bin/heptactl",\n        "lib/systemd/system/hepta-execution-simulator.service",\n        "share/doc/heptatrader/index.md",\n        "share/heptatrader/preflight-policy-v1.json",\n    ]\n    for relative in paths:\n        path = root / relative\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_bytes(f"{marker}:{relative}\\n".encode("utf-8"))\n        path.chmod(0o755 if relative.startswith("bin/") else 0o644)\n    build_info = {\n        "schema": "heptatrader.installed-build.v1",\n        "release_label": VERSION,\n        "project_version": "0.1.0",\n        "ib_api_compiled": False,\n        "paper_authorized": False,\n        "live_authorized": False,\n    }\n    path = root / "share/heptatrader/heptatrader-build-info.json"\n    path.write_text(json.dumps(build_info, sort_keys=True) + "\\n", encoding="utf-8")\n    return root\n\n\ndef package(root: Path, output: Path) -> dict:\n    return release.package_install_root(\n        root,\n        output,\n        version=VERSION,\n        profile="core",\n        source_sha=SOURCE_SHA,\n        source_date_epoch=EPOCH,\n    )\n\n\ndef create_competing_file(directory_fd: int, final_name: str, body: bytes) -> None:\n    descriptor = os.open(\n        final_name,\n        os.O_WRONLY | os.O_CREAT | os.O_EXCL,\n        0o600,\n        dir_fd=directory_fd,\n    )\n    try:\n        view = memoryview(body)\n        while view:\n            written = os.write(descriptor, view)\n            self_remaining = view[written:]\n            view = self_remaining\n        os.fsync(descriptor)\n    finally:\n        os.close(descriptor)\n\n\nclass ReleaseRaceBoundaryTests(unittest.TestCase):\n    def test_concurrent_package_publisher_cannot_be_overwritten(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            work = Path(directory)\n            output = work / "release.tar.gz"\n            sentinel = b"competitor-won\\n"\n            original_publish = release._publish_noreplace\n\n            def race(directory_fd: int, temporary_name: str, final_name: str) -> None:\n                create_competing_file(directory_fd, final_name, sentinel)\n                original_publish(directory_fd, temporary_name, final_name)\n\n            with mock.patch.object(release, "_publish_noreplace", side_effect=race):\n                with self.assertRaisesRegex(\n                    release.PackageError, "refusing to replace existing output"\n                ):\n                    package(fixture_tree(work / "root"), output)\n\n            self.assertEqual(output.read_bytes(), sentinel)\n            self.assertFalse(Path(str(output) + ".sha256").exists())\n            self.assertFalse(Path(str(output) + ".receipt.json").exists())\n\n    def test_payload_archive_uses_the_bytes_hashed_into_manifest(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            work = Path(directory)\n            root = fixture_tree(work / "root")\n            target = root / "bin/heptactl"\n            original = target.read_bytes()\n            payload = release.collect_payload(root)\n            try:\n                manifest = release.build_manifest(\n                    payload, VERSION, "core", SOURCE_SHA, EPOCH\n                )\n                target.write_bytes(b"mutated-after-snapshot\\n")\n                archive_bytes, _ = release.archive_bytes(\n                    payload, manifest, VERSION, "core", EPOCH\n                )\n            finally:\n                release.close_payload(payload)\n\n            with tarfile.open(fileobj=io.BytesIO(archive_bytes), mode="r:gz") as archive:\n                member = archive.getmember(\n                    f"heptatrader-{VERSION}-core/bin/heptactl"\n                )\n                stream = archive.extractfile(member)\n                self.assertIsNotNone(stream)\n                archived = stream.read()\n                manifest_member = archive.getmember(\n                    f"heptatrader-{VERSION}-core/manifest.json"\n                )\n                manifest_stream = archive.extractfile(manifest_member)\n                self.assertIsNotNone(manifest_stream)\n                emitted_manifest = json.loads(manifest_stream.read())\n\n            self.assertEqual(archived, original)\n            entry = next(\n                item\n                for item in emitted_manifest["files"]\n                if item["path"] == "bin/heptactl"\n            )\n            self.assertEqual(entry["sha256"], hashlib.sha256(original).hexdigest())\n            self.assertNotEqual(archived, target.read_bytes())\n\n    def test_preflight_rejects_path_swap_after_pinning_artifact(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            work = Path(directory)\n            artifact = work / "release.tar.gz"\n            original_receipt = package(fixture_tree(work / "root-a", "a"), artifact)\n            replacement = work / "replacement.tar.gz"\n            package(fixture_tree(work / "root-b", "b"), replacement)\n            policy = preflight._load_policy(POLICY)\n            original_inspect = preflight._inspect_archive_stream\n\n            def swap(stream, selected_policy, profile):\n                os.replace(replacement, artifact)\n                return original_inspect(stream, selected_policy, profile)\n\n            with mock.patch.object(\n                preflight, "_inspect_archive_stream", side_effect=swap\n            ):\n                with self.assertRaisesRegex(\n                    preflight.PreflightError, "changed or was replaced"\n                ):\n                    preflight.inspect_archive(\n                        artifact,\n                        original_receipt["package_sha256"],\n                        policy,\n                        "core",\n                    )\n\n    def test_concurrent_receipt_publisher_cannot_be_overwritten(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            path = Path(directory) / "preflight.json"\n            sentinel = b"independent-receipt\\n"\n            original_publish = preflight._publish_noreplace\n\n            def race(directory_fd: int, temporary_name: str, final_name: str) -> None:\n                create_competing_file(directory_fd, final_name, sentinel)\n                original_publish(directory_fd, temporary_name, final_name)\n\n            with mock.patch.object(preflight, "_publish_noreplace", side_effect=race):\n                with self.assertRaisesRegex(\n                    preflight.PreflightError,\n                    "refusing to replace existing receipt",\n                ):\n                    preflight._write_private_receipt(\n                        path,\n                        {\n                            "schema": preflight.RECEIPT_SCHEMA,\n                            "result": "PASS",\n                            "authorization_effect": "NONE",\n                            "paper_authorized": False,\n                            "live_authorized": False,\n                        },\n                    )\n\n            self.assertEqual(path.read_bytes(), sentinel)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one marker, found {count}")
    return text.replace(old, new, 1)


def replace_between(
    text: str, start: str, end: str, replacement: str, label: str
) -> str:
    start_index = text.find(start)
    if start_index < 0:
        raise RuntimeError(f"{label}: start marker missing")
    end_index = text.find(end, start_index + len(start))
    if end_index < 0:
        raise RuntimeError(f"{label}: end marker missing")
    return text[:start_index] + replacement.rstrip() + "\n\n" + text[end_index:]


def patch_builder() -> None:
    path = ROOT / "scripts/build_release_package.py"
    text = path.read_text(encoding="utf-8")
    text = replace_once(
        text,
        "import re\nimport shutil",
        "import re\nimport secrets\nimport shutil",
        "builder imports/secrets",
    )
    text = replace_once(
        text,
        "from typing import Any, Iterable",
        "from typing import Any, BinaryIO, Iterable",
        "builder imports/BinaryIO",
    )
    text = replace_between(
        text,
        "def sha256_file(path: Path) -> str:\n",
        "\ndef validate_identity(",
        "",
        "remove path-reopening hash helper",
    )
    marker = "class PackageError(ValueError):\n    pass\n\n"
    text = replace_once(
        text,
        marker,
        marker + BUILD_HELPERS.strip() + "\n\n",
        "insert builder descriptor helpers",
    )
    old_payload = """@dataclass(frozen=True)
class PayloadFile:
    path: str
    source: Path
    size: int
    mode: int
    sha256: str
"""
    new_payload = """@dataclass(frozen=True)
class PayloadFile:
    path: str
    source: Path
    snapshot: BinaryIO
    size: int
    mode: int
    sha256: str
"""
    text = replace_once(text, old_payload, new_payload, "PayloadFile snapshot")
    text = replace_between(
        text,
        "def collect_payload(root: Path) -> list[PayloadFile]:\n",
        "\ndef build_manifest(",
        BUILD_COLLECT,
        "collect payload snapshots",
    )
    text = replace_between(
        text,
        "def archive_bytes(\n",
        "\ndef _ensure_new_outputs(",
        BUILD_ARCHIVE,
        "archive pinned snapshots",
    )
    text = replace_between(
        text,
        "def _ensure_new_outputs(paths: Iterable[Path]) -> None:\n",
        "\ndef package_install_root(",
        BUILD_PUBLISH,
        "no-replace publication",
    )
    text = replace_between(
        text,
        "def package_install_root(\n",
        "\ndef install_from_build(",
        BUILD_PACKAGE,
        "package transaction",
    )
    compile(text, str(path), "exec")
    path.write_text(text, encoding="utf-8")


def patch_preflight() -> None:
    path = ROOT / "scripts/hepta_preflight.py"
    text = path.read_text(encoding="utf-8")
    text = replace_once(
        text,
        "import argparse\nfrom datetime",
        "import argparse\nfrom dataclasses import dataclass\nfrom datetime",
        "preflight imports/dataclass",
    )
    text = replace_once(
        text,
        "import re\nimport shutil",
        "import re\nimport secrets\nimport shutil",
        "preflight imports/secrets",
    )
    marker = "class DuplicateKeyError(ValueError):\n    pass\n\n"
    text = replace_once(
        text,
        marker,
        marker + PREFLIGHT_HELPERS.strip() + "\n\n",
        "insert preflight descriptor helpers",
    )
    text = replace_between(
        text,
        "def sha256_file(path: Path) -> str:\n",
        "\ndef _read_bounded(",
        "",
        "remove preflight path hash helper",
    )
    text = replace_between(
        text,
        "def _load_policy(path: Path) -> dict[str, Any]:\n",
        "\ndef _canonical_member_name(",
        PREFLIGHT_LOAD_POLICY,
        "pin policy bytes",
    )
    text = replace_between(
        text,
        "def inspect_archive(\n",
        "\ndef _machine_id_digest(",
        PREFLIGHT_INSPECT,
        "pin archive bytes",
    )
    text = replace_between(
        text,
        "def _write_private_receipt(path: Path, value: dict[str, Any]) -> None:\n",
        "\ndef run_preflight(",
        PREFLIGHT_WRITE,
        "receipt no-replace publication",
    )
    text = replace_once(
        text,
        "policy = _load_policy(args.policy.resolve(strict=True))",
        "policy = _load_policy(_absolute_path(args.policy))",
        "policy path opening",
    )
    text = replace_once(
        text,
        "args.artifact.resolve(strict=True), args.expected_sha256, policy, args.profile",
        "_absolute_path(args.artifact), args.expected_sha256, policy, args.profile",
        "artifact path opening",
    )
    compile(text, str(path), "exec")
    path.write_text(text, encoding="utf-8")


def patch_catalog() -> None:
    path = ROOT / "docs/module-catalog.json"
    text = path.read_text(encoding="utf-8")
    old = (
        '"tests": ["tests/python/test_release_package.py", '
        '"tests/python/test_hepta_preflight.py", '
        '"tests/python/test_cmake_install_integration.py"],'
    )
    new = (
        '"tests": ["tests/python/test_release_package.py", '
        '"tests/python/test_release_security_races.py", '
        '"tests/python/test_hepta_preflight.py", '
        '"tests/python/test_cmake_install_integration.py"],'
    )
    text = replace_once(text, old, new, "release-engineering tests")
    path.write_text(text, encoding="utf-8")


def main() -> int:
    patch_builder()
    patch_preflight()
    patch_catalog()
    test_path = ROOT / "tests/python/test_release_security_races.py"
    if test_path.exists() or test_path.is_symlink():
        raise RuntimeError(f"refusing to replace existing test: {test_path}")
    compile(RACE_TEST, str(test_path), "exec")
    test_path.write_text(RACE_TEST, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
